/* A reader for signed public editions. No world-state, private draft or provider access. */
(function(root){
 'use strict';const SP=root.SP,G=SP?.game,D=root.document;if(!G||!D||SP.mediaNewsUI)return;
 const mounts=new WeakMap(),channels={weather:'槐城天气',neighborhood:'街区公众号'},CSS=D.currentScript?.src?new URL('media_news.css',D.currentScript.src).href:'js/media_news.css';let styled=false;
 const stamp=at=>Number.isFinite(at)&&at>=0?'第'+(Math.floor(at/1440)+1)+'天 '+String(Math.floor(at%1440/60)).padStart(2,'0')+':'+String(Math.floor(at%60)).padStart(2,'0'):'签发时间待确认';
 const published=a=>a&&Number.isSafeInteger(a.id)&&a.id>0&&Object.hasOwn(channels,a.channelId)&&typeof a.title==='string'&&typeof a.body==='string';
 function style(){if(styled)return;styled=true;const link=D.createElement('link');link.rel='stylesheet';link.href=CSS;link.setAttribute('data-media-news-style','true');D.head?.appendChild?.(link);}
 function render(parent,{isCurrent=()=>true}={}){
  style();const owner=G.ps,token={},valid=()=>owner===G.ps&&isCurrent()&&mounts.get(parent)===token;mounts.set(parent,token);
  let caseId=null,page=0,subscribedOnly=false,channel='all',detail=null,message='',epoch=0,listScroll=0,returning=false,returnId=null,first=true;
  function node(tag,value,host,cls=''){const n=D.createElement(tag);n.textContent=value==null?'':String(value);if(cls)n.className=cls;host.appendChild(n);return n;}
  function button(label,fn,host,cls=''){const version=epoch,b=node('button',label,host,'mn-button '+cls);b.type='button';b.style.minHeight='44px';b.onclick=()=>valid()&&epoch===version?fn():false;return b;}
  function view(){try{if(caseId!==null)return SP.mediaNews?.view?.({page,pageSize:8,subscribedOnly,caseId});if(channel==='all')return SP.mediaNews?.view?.({page,pageSize:8,subscribedOnly});const first=SP.mediaNews?.view?.({page:0,pageSize:32,subscribedOnly});if(!first||!Array.isArray(first.articles))return first;const rows=first.articles.filter(published);for(let p=1,total=Math.min(8,Number.isSafeInteger(first.totalPages)?first.totalPages:1);p<total;p++){const v=SP.mediaNews.view({page:p,pageSize:32,subscribedOnly});if(!valid()||!Array.isArray(v?.articles))return null;rows.push(...v.articles.slice(0,32).filter(published));}const unique=[...new Map(rows.filter(a=>a.channelId===channel).map(a=>[a.id,a])).values()],totalPages=Math.max(1,Math.ceil(unique.length/8)),p=Math.min(page,totalPages-1);return{...first,page:p,totalPages,articles:unique.slice(p*8,(p+1)*8)};}catch{return null;}}
  function issue(a,host){node('span',channels[a.channelId],host,'mn-channel');node('span',stamp(a.issuedAt),host,'mn-time');}
  function forecast(a,host,hero=false){if(a.kind!=='forecast'&&!Number.isFinite(a.fogProbability))return;if(Number.isFinite(a.targetDay))node('p','目标：第'+(Math.floor(a.targetDay)+1)+'天',host,'mn-forecast-day');if(Number.isFinite(a.fogProbability)&&a.fogProbability>=0&&a.fogProbability<=1){const stat=node('div','',host,'mn-forecast-stat');node('strong',Number((a.fogProbability*100).toFixed(1))+'%',stat);node('span','有雾概率',stat);stat.setAttribute('aria-label','有雾概率 '+Number((a.fogProbability*100).toFixed(1))+'%');}node('p','游戏规则概率预报 · 不保证实际天气',host,hero?'mn-forecast-note':'mn-source');}
  function read(a){const r=SP.mediaNews?.markRead?.(a.id);if(!r?.ok){message=r?.reason||'该版次暂不可读，请刷新。';return draw();}listScroll=parent.scrollTop||0;returnId=a.id;detail={id:a.id,channelId:a.channelId,title:a.title,body:a.body,issuedAt:a.issuedAt,sourceLabel:a.sourceLabel,kind:a.kind,sourceKey:a.sourceKey,targetDay:a.targetDay,fogProbability:a.fogProbability};return draw();}
  function draw(){if(!valid())return false;const v=view();if(!valid())return false;const scroll=first?0:detail?0:returning?listScroll:parent.scrollTop||0;first=false;returning=false;epoch++;parent.replaceChildren();const app=node('section','',parent,'mn-app');app.setAttribute('aria-label','槐城闻讯 · 新闻与公众号');
   const mast=node('header','',app,'mn-masthead'),brand=node('div','',mast,'mn-brand');node('span','闻',brand,'mn-brand-mark');const names=node('div','',brand);node('p','HUAICHENG / EDITIONS',names,'mn-kicker');node('h2','槐城·闻讯',names,'mn-brand-title');
   if(!v||!Array.isArray(v.articles)){node('p','新闻暂时还未准备好，请稍后再看。',app,'mn-empty');parent.scrollTop=0;return false;}
   const articles=v.articles.filter(published),meta=node('div','',app,'mn-edition');const ats=articles.map(a=>a.issuedAt).filter(n=>Number.isFinite(n)&&n>=0);node('span',ats.length?'公开版次 · '+stamp(Math.max(...ats)):'公开版次',meta);if(Number.isSafeInteger(v.unread)&&v.unread>=0)node('span','未读 '+v.unread+' 篇',meta,'mn-unread');
   if(typeof v.statusReason==='string'&&v.statusReason.trim())node('p',v.statusReason,app,'mn-notice');if(message){const n=node('p',message,app,'mn-notice mn-feedback');n.setAttribute('role','status');}
   if(detail){const a=detail;if(a.kind==='case'&&typeof a.sourceKey==='string')button('跟踪此事件的后续报道',()=>{caseId=a.sourceKey.split(':')[0]+':'+a.sourceKey.split(':').at(-1);detail=null;page=0;return draw();},app,'mn-case-follow');button('返回新闻列表',()=>{detail=null;message='';returning=true;return draw();},app,'mn-back');const article=node('article','',app,'mn-reader'),byline=node('div','',article,'mn-byline');issue(a,byline);const title=node('h3',a.title,article,'mn-reader-title');title.setAttribute('tabindex','-1');forecast(a,article);const body=node('p',a.body,article,'mn-reader-body');body.style.whiteSpace='pre-wrap';node('p','来源：'+(typeof a.sourceLabel==='string'?a.sourceLabel:'公开版次'),article,'mn-source');node('p','已阅读本公开版次',article,'mn-reader-end');parent.scrollTop=0;title.focus?.();return true;}
   if(caseId!==null){node('p','正在跟踪事件 #'+String(caseId).replace('city:','').replace('conflict:','C').replace('civic:','招领 '),app,'mn-notice');button('返回全部报道',()=>{caseId=null;page=0;return draw();},app,'mn-back');}const tools=node('div','',app,'mn-tools'),chips=node('nav','',tools,'mn-chips');chips.setAttribute('aria-label','资讯频道');for(const [id,label]of[['all','全部'],['weather','天气'],['neighborhood','街区']]){const b=button(label,()=>{channel=id;page=0;message='';parent.scrollTop=0;return draw();},chips,'mn-chip'+(channel===id?' is-active':''));b.setAttribute('aria-pressed',String(channel===id));}const following=button(subscribedOnly?'查看全部新闻':'只看已关注',()=>{subscribedOnly=!subscribedOnly;page=0;message='';parent.scrollTop=0;return draw();},chips,'mn-chip mn-follow-filter'+(subscribedOnly?' is-active':''));following.setAttribute('aria-pressed',String(subscribedOnly));
   const section=node('div','',app,'mn-section-heading');node('h3','我的频道',section);button('刷新公开版次',()=>{const r=SP.mediaNews?.refresh?.();message=r?.ok?'已核对当前公开版次。':r?.reason||'暂时无法刷新，请稍后再看。';return draw();},section,'mn-refresh');
   const subscriptions=node('div','',app,'mn-subscriptions');for(const [id,name]of Object.entries(channels)){const card=node('section','',subscriptions,'mn-subscription');node('span',id==='weather'?'气象':'街区',card,'mn-channel-icon '+id);node('strong',name,card);const followed=v.subscriptions?.[id]===true;const b=button((followed?'取消关注 · ':'关注 · ')+name,()=>{const r=SP.mediaNews?.setSubscribed?.(id,!followed);message=r?.ok?(followed?'已取消关注。':'已关注；可在已关注列表查看公开版次。'):r?.reason||'本次关注未完成。';return draw();},card,'mn-subscribe'+(followed?' is-followed':''));b.setAttribute('aria-pressed',String(followed));}
   const forecastArticle=articles.find(a=>a.kind==='forecast'&&Number.isFinite(a.fogProbability)&&a.fogProbability>=0&&a.fogProbability<=1),readButtons=[];
   if(forecastArticle){const a=forecastArticle,hero=node('article','',app,'mn-weather-card');node('p','WEATHER / 槐城天气',hero,'mn-weather-kicker');node('h3',a.title,hero);forecast(a,hero,true);node('p','来源：'+(typeof a.sourceLabel==='string'?a.sourceLabel:'公开版次'),hero,'mn-weather-source');const bottom=node('div','',hero,'mn-weather-bottom');node('span',stamp(a.issuedAt),bottom);const b=button('阅读全文 · '+a.title,()=>read(a),bottom,'mn-open mn-weather-open');readButtons.push([a.id,b]);}
   const feedHeading=node('div','',app,'mn-section-heading mn-feed-heading');node('h3',channel==='weather'?'天气版次':channel==='neighborhood'?'街区资讯':'本页资讯',feedHeading);node('span','已签发 / 公开阅读',feedHeading,'mn-source');
   if(!articles.length)node('p',subscribedOnly?'已关注的公众号还没有可读版次。':'暂时没有已签发的新闻。',app,'mn-empty');
   for(const a of articles){if(a===forecastArticle)continue;const card=node('article','',app,'mn-article-card'),byline=node('div','',card,'mn-byline');issue(a,byline);node('h3',a.title,card,'mn-article-title');node('p',Array.from(a.body).slice(0,96).join('')+(Array.from(a.body).length>96?'…':''),card,'mn-excerpt');const footer=node('div','',card,'mn-article-footer');node('span','来源：'+(typeof a.sourceLabel==='string'?a.sourceLabel:'公开版次'),footer,'mn-source');const b=button('阅读全文 · '+a.title,()=>read(a),footer,'mn-open');readButtons.push([a.id,b]);}
   const total=Number.isSafeInteger(v.totalPages)&&v.totalPages>0?v.totalPages:1,current=Number.isSafeInteger(v.page)&&v.page>=0?v.page:page;page=Math.min(current,total-1);const pages=node('nav','',app,'mn-pagination');pages.setAttribute('aria-label','公开版次分页');const prev=button('上一页',()=>{page=Math.max(0,page-1);parent.scrollTop=0;return draw();},pages,'mn-page');prev.disabled=page<=0;node('span','第 '+(page+1)+' / '+total+' 页',pages);const next=button('下一页',()=>{page=Math.min(total-1,page+1);parent.scrollTop=0;return draw();},pages,'mn-page');next.disabled=page>=total-1;
   node('p','公开版次阅读 · 刷新不发送采访或调用AI',app,'mn-footer-note');parent.scrollTop=scroll;if(returnId!==null){readButtons.find(([id])=>id===returnId)?.[1]?.focus?.({preventScroll:true});returnId=null;}return true;
  }
  return draw();
 }
 SP.mediaNewsUI={render};
})(window);
